#!/usr/bin/env node
// Copies the API types from the private @docksy/shared package into this package,
// so the published d.ts is self-contained. Run after packages/shared changes:
//   node packages/client/scripts/sync-types.mjs
// src/types.test.ts fails when the copy drifts.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const HEADER =
  '// GENERATED by packages/client/scripts/sync-types.mjs from packages/shared/src/index.ts. Do not edit by hand.\n\n';

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
export const SHARED_PATH = here('../../shared/src/index.ts');
export const TYPES_PATH = here('../src/types.ts');

export function render(shared) {
  return HEADER + shared;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(TYPES_PATH, render(readFileSync(SHARED_PATH, 'utf8')));
  console.log(`synced ${TYPES_PATH}`);
}
